import java.util.*;

class Solution {
    public int[] sortedSquares(int[] nums) {
        int n = nums.length;
        int[] res = new int[n];
        int l = 0, r = n - 1;
        for (int pos = n - 1; pos >= 0; pos--) { // fill from the back with the biggest square
            if (Math.abs(nums[l]) > Math.abs(nums[r])) {
                res[pos] = nums[l] * nums[l];
                l++;
            } else {
                res[pos] = nums[r] * nums[r];
                r--;
            }
        }
        return res;
    }
}

