class Solution:
    def sortedSquares(self, nums: List[int]) -> List[int]:
        n = len(nums)
        res = [0] * n
        l, r = 0, n - 1
        for pos in range(n - 1, -1, -1):
            if abs(nums[l]) > abs(nums[r]):
                res[pos] = nums[l] * nums[l]; l += 1
            else:
                res[pos] = nums[r] * nums[r]; r -= 1
        return res
